-- Jefferson Scholarship rewritten in plain steps from the Foundation's own pages (checked 1 Nov 2026), and the Walentas Scholarship added.
-- Source pages: jeffersonscholars.org/scholarships, /scholarships/walentas-faqs, /scholarship/selection/eligibility
-- Safe to run more than once. Both rows stay verified = false until you check them.
update public.scholarships set
  criteria = 'Who is eligible: Students in their final year of secondary school. Citizenship is not a selection criterion, so international students can be considered. Selection is based on academic strength, leadership and citizenship. Financial need is not considered. You must not have been nominated before for a Jefferson or Walentas Scholarship. Requirements: You cannot apply yourself. Your school must nominate you, so ask your counsellor to nominate you. A school can only nominate if it is registered with the Foundation and located in one of its nominating regions. The Foundation page does not say if schools in Ghana can take part. Email selection@jeffersonscholars.org to ask before you plan around this. You must also meet UVA undergraduate admission requirements and apply to UVA yourself (Early Decision, Early Action or Regular Decision). How to apply: Step 1: Ask your counsellor to nominate you. Step 2: Your school sends the nominee information, one recommendation letter, your transcript and the school profile. Step 3: You send your contact details, activities, awards, a personal essay and a leadership essay. Step 4: Regional interviews are usually in January and final interviews in late February. Deadline: 1 December 2026 for both the school materials and your own materials. Decisions are generally due in mid-April.',
  award_note = 'Intended to cover the full cost of attendance for four years at the University of Virginia: tuition, room and board, enrichment, international travel and career development. The Foundation lists more than USD 42,000 a year for Virginia residents and more than USD 83,000 a year for non-residents.'
where name = 'Jefferson Scholarship';

insert into public.scholarships (name, funder, country, funding_type, level, criteria, award_note, link, source_url, school_id, deadline, verified, demo)
select 'Walentas Scholarship', j.funder, j.country, 'Full', 'Undergraduate',
  'Who is eligible: Students in their final year of school who are first-generation and college-bound: neither parent nor guardian has earned a bachelor''s degree or its international equivalent. They must show excellence or potential in leadership, scholarship and citizenship. U.S. citizenship is not required. Financial need is not considered. Requirements: You cannot apply yourself. Your school must nominate you. Only schools located in the United States can nominate for the Walentas Scholarship, so a school in Ghana cannot. A Ghanaian first-generation student may still be nominated for the Jefferson Scholarship instead, if the school is able to take part. You must also gain admission to UVA. How to apply: Step 1: Your counsellor nominates you. Step 2: Your school sends nominee information, one recommendation letter, a transcript and the school profile. Step 3: You send your contact details, activities, awards, a personal essay and a leadership essay. Final selection interviews are held virtually in late February 2027. Deadline: 1 December 2026 for school and student materials. SAT, ACT, AP and IB scores are not considered for 2026-2027.',
  'Full scholarship for four years (eight semesters of full-time study) at the University of Virginia: tuition, room, board, books and miscellaneous expenses. It can only be used at UVA.',
  'https://www.jeffersonscholars.org/scholarships/walentas-faqs', 'https://www.jeffersonscholars.org/scholarships/walentas-faqs', j.school_id, j.deadline, false, false
from public.scholarships j
where j.name = 'Jefferson Scholarship'
  and not exists (select 1 from public.scholarships w where w.name = 'Walentas Scholarship');

select name, funding_type, deadline, school_id is not null as has_school from public.scholarships where name in ('Jefferson Scholarship', 'Walentas Scholarship');
